export const levelKey = (lvl) => (lvl < 5 ? 'rust' : lvl < 10 ? 'city' : lvl < 28 ? 'tuning' : 'sport');
export const levelPartTier = (lvl) => (lvl < 10 ? 'stock' : lvl < 20 ? 'street' : 'sport');

