export function fmt(n) {
  return Math.round(n).toLocaleString('uk-UA').replace(/ /g, ' ') + ' ' + CURRENCY;
}
export function short(n) {
  const a = Math.abs(n);
  const t = (x, d) => x.toFixed(d).replace(/\.0+$/, '').replace('.', ',');
  if (a >= 1e9) return t(n / 1e9, a >= 1e10 ? 0 : 1) + ' млрд ₴';
  if (a >= 1e6) return t(n / 1e6, a >= 1e7 ? 0 : 1) + ' млн ₴';
  if (a >= 1e4) return Math.round(n / 1e3) + ' тис ₴';
  return fmt(n);
}

// ---------- seasons ----------
// A season lasts two weeks; season 1 starts 20.10.2026 at 00:00 Kyiv time. Nothing is wiped: cars, money and collections stay. Each
// season has its own pass (30 levels of season XP — the same XP the player earns anyway), its own rating by season
// XP with prizes in stars (spent in the shop), and a car you can only get that season.
export const SEASON = { start: Date.UTC(2026, 9, 19, 21), days: 14, levels: 30, premiumStars: 250 };
export const seasonOf = (t) => Math.max(1, Math.floor((t - SEASON.start) / (SEASON.days * 86400e3)) + 1);
export const seasonStartOf = (n) => SEASON.start + (n - 1) * SEASON.days * 86400e3;
export const seasonEndOf = (n) => seasonStartOf(n + 1);
// Season XP from one pass level to the next: an active player (~2,000 XP a day) reaches level 30 in about 12 days,
// a casual one gets halfway.
export const passXpFor = (lvl) => 300 + 40 * lvl;
export function passLevel(xp) {
  let lvl = 1, left = xp;
  while (lvl < SEASON.levels && left >= passXpFor(lvl)) left -= passXpFor(lvl++);
  return { level: lvl, xp: left, need: lvl < SEASON.levels ? passXpFor(lvl) : 0 };
}
const passMoney = (l) => niceRound(16000 * Math.pow(l, 1.5));
// Money of a level grows with the player's garage: passHours(l) hours of the hourly income (`rate`, capped at
// SEASON_RATE_CAP), never less than the base curve (45 тис at level 2 → 2,6 млн at 30). A casual garage (≤ 300 тис/год)
// gets exactly the base; a late one (3,5 млн/год) ~1 h of income per level, 0,3 h at level 2 → 1,5 h at 30.
export const SEASON_RATE_CAP = 10000000;
export const passHours = (l) => 0.2 + 0.045 * l;
export const passMoneyFor = (l, rate = 0) => Math.max(passMoney(l), niceRound(Math.max(1000, Math.min(SEASON_RATE_CAP, rate || 0) * passHours(l))));
// Free and premium rewards for each level 2…30 (level 1 is where everyone starts). rate: the player's garage income
// per hour (scales the money); every 5th level of the free track adds a season cosmetic (passCosmetic).
export function passReward(season, lvl, premium, rate = 0) {
  if (!premium) {
    const r = { money: passMoneyFor(lvl, rate) };
    const cos = passCosmetic(season, lvl);
    if (cos) r.cosmetic = cos.id;
    if (lvl === 5) r.caseId = 'city';
    if (lvl === 10) Object.assign(r, { caseId: 'sport', slots: 1 });
    if (lvl === 15) Object.assign(r, { parts: 2, tier: 'sport' });
    if (lvl === 20) Object.assign(r, { caseId: 'premium', slots: 1 });
    if (lvl === 25) Object.assign(r, { parts: 2, tier: 'pro' });
    if (lvl === 30) Object.assign(r, { caseId: 'elite', slots: 2 });
    return r;
  }
  if (lvl === 30) return { seasonCar: SEASON_CARS.find((c) => c.season === season)?.id || SEASON_CARS[SEASON_CARS.length - 1].id };
  if (lvl === 5) return { caseId: 'sport' };
  if (lvl === 10) return { caseId: 'elite' };
  if (lvl === 15) return { caseId: 'sport', count: 2 };
  if (lvl === 20) return { caseId: 'elite' };
  if (lvl === 25) return { caseId: 'elite', count: 2 };
  if (lvl % 2 === 0) return { money: passMoneyFor(lvl, rate) };
  return { parts: lvl < 10 ? 2 : 1, tier: lvl < 10 ? 'street' : lvl < 20 ? 'sport' : 'pro' };
}
// Season cosmetics of the free track (every 5 levels), kept as claims "cos:s<season>:<kind>". Liveries go through the
// paint shop (free on any own car once earned), the frame goes round the owner's plates, the backdrop behind the
// showcase, the badge into the profile. Exclusive: nothing else gives them.
export const PASS_COSMETICS = { 5: 'livery', 10: 'frame', 15: 'showcase', 20: 'gold', 25: 'badge' };
// Themed seasons (from season 2): a name for the pass screen, their own names and looks for the cosmetics, and a sixth
// cosmetic at level 30 of the free track (an underglow). Season 1 keeps its five «Сезон 1» items exactly as they were.
export const SEASON_THEMES = {
  2: { name: 'Нічний Токіо', tagline: 'неон, естакади й дрифт до ранку', color: '#ff2bd6', accent: '#00e5ff', look: 'season2',
    cos: { livery: 'Ліврея «Неон Сібуя»', frame: 'Рамка номера «Ханко»', showcase: 'Фон вітрини «Шуто-експрес»', gold: 'Ліврея «Сакура · Золото»', badge: 'Значок «Нічний Токіо»', glow: 'Підсвітка «Токійський неон»' },
    liveries: { szn: 'Неон Сібуя', gold: 'Сакура · Золото' } },
};
