// «1 справжнє авто», «3 справжні авто», «177 справжніх авто».
function realCars(n) {
  const a = n % 10, b = n % 100;
  return a === 1 && b !== 11 ? 'справжнє авто' : a >= 2 && a <= 4 && (b < 12 || b > 14) ? 'справжні авто' : 'справжніх авто';
}
