// Season liveries (passCosmetic: levels 5 and 20 of the pass): not on sale, free on any own car once earned (the claim
// in `cos`). Ids "szn<n>" / "szn<n>g"; public/paint.js draws them with the season number on the door.
for (let n = 1; n <= 26; n++) {
  LIVERY_BY_ID['szn' + n] = { id: 'szn' + n, name: `Сезон ${n}`, hint: 'нагорода пропуску', season: n, cos: `cos:s${n}:livery` };
  LIVERY_BY_ID['szn' + n + 'g'] = { id: 'szn' + n + 'g', name: `Сезон ${n} · Золото`, hint: 'нагорода пропуску', season: n, gold: true, cos: `cos:s${n}:gold` };
  const th = SEASON_THEMES[n]?.liveries;
  if (th) Object.assign(LIVERY_BY_ID['szn' + n], { name: th.szn }), Object.assign(LIVERY_BY_ID['szn' + n + 'g'], { name: th.gold });
}
// «Стиль» liveries (STYLE_ITEMS, kind livery): bought for stars once, then free on any own car (the claim in `cos`).
for (const it of STYLE_ITEMS.filter((x) => x.kind === 'livery')) LIVERY_BY_ID[it.look] = { id: it.look, name: it.name.replace(/^Ліврея «(.+)»$/, '$1'), hint: it.hint, star: true, cos: it.cos };

// ---------- career: country bosses («Кар'єра») ----------
// A ladder of named bosses, country by country (Україна → Японія → Німеччина → Китай → США → Британія → Італія). Each
// boss drives a real car of that country with a full kit of one parts tier (exactly what a player can build: its shown
// power and pace are carStats of that car), driven by an AI of a fixed level — the pace never depends on the player.
// Bosses open one after another (the next after the previous is beaten); a boss takes the challenge only from a car of
// its class or higher (`req`). The first win pays the boss's one-time reward (no entry, a loss costs only the fuel);
// rematches pay like a normal race (bossRematch). The reward money is set by hand per boss: ~4–8 races' worth for a
// player of that stage (raceEv of a typical car of `req`), a country's last boss ~2× plus two keys of the country case,
