export const BOSS_COUNTRIES = Object.keys(BOSS_RAW);
// The career badge after each country (one badge «boss» in the profile, replaced by the next): title and tier (colour).
export const BOSS_BADGES = {
  UA: ['Король району · Україна', 0], JP: ['Король доріг · Японія', 1], DE: ['Король автобану · Німеччина', 1], CN: ['Король доріг · Китай', 2],
  US: ['Король хайвею · США', 2], GB: ['Король доріг · Британія', 3], IT: ['Бос усіх босів', 3],
};
// The pretty plate a country's last boss gives (its class — the plate's value range, PLATE_VALUE).
export const BOSS_PLATE = { UA: 'C', JP: 'C', DE: 'B', CN: 'B', US: 'A', GB: 'A', IT: 'S' };
const bossKit = (model, tier) => (tier ? Object.fromEntries(partKeysOf(model).map((k) => [k, tier])) : {});
// The parts a boss (or its hard rematch, S.bossHard) runs on — for the race result's explanation (raceWhy).
export const bossParts = (b) => bossKit(b.model, b.kit);
export const BOSSES = [];
for (const c of BOSS_COUNTRIES) {
  BOSS_RAW[c].forEach(([id, nick, car, kit, ai, req, taunt, money, parts], i, list) => {
    const model = ALL_MODELS.find((m) => m.name === car && !m.secret)?.id;
    if (!model) throw new Error('boss car ' + car);
    const st = carStats({ model, parts: bossKit(model, kit) });
    const final = i === list.length - 1;
    const reward = { money, ...(parts ? { parts: parts[0], tier: parts[1] } : {}), ...(final ? { caseId: 'c-' + c.toLowerCase(), count: 2, plate: BOSS_PLATE[c], badge: BOSS_BADGES[c][0] } : {}) };
    BOSSES.push({ id, n: BOSSES.length, country: c, nick, model, kit, ai, req, taunt, final, reward, hp: st.hp, base: st.base, shift: st.shift, et: st.et });
  });
}
// Class windows («вікно класу»): a boss races cars from its `req` class up to `max` only — so one strong car can't
// clear the whole career — and a country's final boss (`own`) only a car of its own country. 'X' = no upper bound.
export const BOSS_MAX = {
  'ua-panas': 'C', 'ua-zhora': 'C', 'ua-tolik': 'C', 'ua-general': 'C',
  'jp-takumi': 'C', 'jp-sensei': 'C', 'jp-ninja': 'B', 'jp-godzilla': 'B',
  'de-hans': 'B', 'de-bumer': 'B', 'de-emka': 'B', 'de-kaiser': 'A',
  'cn-li': 'A', 'cn-dragon': 'A', 'cn-emperor': 'S',
  'us-cowboy': 'A', 'us-tesliar': 'A', 'us-sapphire': 'A', 'us-sheriff': 'S',
  'gb-lord': 'S', 'gb-agent': 'X', 'gb-volt': 'X', 'gb-king': 'X',
  'it-toro': 'X', 'it-don': 'X', 'it-maestro': 'X', 'it-boss': 'X',
};
for (const b of BOSSES) Object.assign(b, { max: BOSS_MAX[b.id] || 'X', own: b.final });
export const BOSS_BY_ID = Object.fromEntries(BOSSES.map((b) => [b.id, b]));
// "лише B", "C–B", "S і вище".
export const bossWindowText = (b) => (b.max === b.req ? `лише ${b.req}` : b.max === 'X' ? `${b.req} і вище` : `${b.req}–${b.max}`);
export const BOSS_COUNTRY_ADJ = { UA: 'українська чи радянська', JP: 'японська', DE: 'німецька', CN: 'китайська', US: 'американська', GB: 'британська', IT: 'італійська' };
// "машина класу C–B" / "японська машина класу C–B".
export const bossNeedText = (b) => `${b.own ? BOSS_COUNTRY_ADJ[b.country] + ' ' : ''}машина класу ${b.req === b.max ? b.req : bossWindowText(b)}`;
// A few cars that fit, cheapest first — for a garage with none of them.
export function bossCarHint(b, n = 3) {
  return ALL_MODELS.filter((m) => !m.secret && bossFits(b, m.id)).sort((x, y) => x.price - y.price).slice(0, n).map((m) => m.id);
}
// «Реванш · складний» (after the first win, once a day per boss): the same boss one parts tier up (no kit → Stock) and
// one driver level up (a legend becomes a champion), for twice the rematch prize. BOSS_HARD.kit overrides the kit
// where a tier up would leave no car of the window a chance (tools/boss-ladder.mjs prints the odds).
export const BOSS_HARD = { prizeMult: 2, kit: { 'us-sheriff': 'pro' } };
const BOSS_AI_UP = { street: 'pro', pro: 'ace', ace: 'legend', legend: 'champ' };
const bossHardCache = {};
export function bossHard(b) {
  if (bossHardCache[b.id]) return bossHardCache[b.id];
  const kit = BOSS_HARD.kit[b.id] || (b.kit ? TIERS[Math.min(TIERS.length - 1, TIER_BY_ID[b.kit].index + 1)].id : TIERS[0].id);
  const st = carStats({ model: b.model, parts: bossKit(b.model, kit) });
  return (bossHardCache[b.id] = { ...b, hard: true, kit, ai: BOSS_AI_UP[b.ai] || b.ai, hp: st.hp, base: st.base, shift: st.shift, et: st.et });
}
// One run of the boss (the server keeps the exact time until the finish, as for any solo rival).
export const bossRun = (rand, b) => humanRun({ base: b.base, shift: b.shift }, BOSS_AI[b.ai], rand);
// How much slower than its base the boss runs (like rivalOffsets, with the boss's own driver).
export function bossOffsets(b, seed = 7) {
  const rand = seededRand(seed + Math.round(b.base * 100));
  return Array.from({ length: RIVAL_SAMPLES }, () => bossRun(rand, b) - b.base);
}
// A car inside the boss's class window (secret and season cars count as above S), of its country for a final.
export const bossFits = (b, model) => {
  const m = MODELS[model], r = rankOf(m.cls);
  return r >= rankOf(b.req) && r <= rankOf(b.max || 'X') && (!b.own || m.country === b.country);
};
// Rematch money, as a normal race: priced by the cheaper of your model and the boss's (an overpowered car racing an
// early boss earns that boss's stakes, not its own), and set so that a GOOD driver in your car as it is (parts
// count) earns ~0.9 raceEv per race at their chance `p` (raceMoney's formula; `p` clamped to the tier range, so a
// sure win pays about an easy race and a long shot about a hard one). `p` never depends on the player's history.
export function bossRematch(p, price) {
  const c = Math.max(0.2, Math.min(0.95, p));
  return raceMoney({ ev: 0.9, chance: c, entry: c >= 0.7 ? 0.35 : c >= 0.4 ? 0.3 : 0.1 }, price);
}
// Text of a boss reward: "200 тис ₴ + 2 × ключ «Україна/СРСР» + номер класу C + значок «…»".
export function bossRewardText(rw) {
  const out = [achRewardText(rw)];
  if (rw.plate) out.push(`номер класу ${rw.plate}`);
  if (rw.badge) out.push(`значок «${rw.badge}»`);
  return out.filter(Boolean).join(' + ');
}
// ---------- dream car: the player's goal from the catalogue (any non-secret car) ----------
// Which cases can drop the model and with what chance (base odds, no events/luck): [{ caseId, pct }] best first.
export function dreamChances(modelId) {
  const m = MODELS[modelId];
  if (!m || m.secret) return [];
  const out = [];
  for (const cs of CASES) {
    if (cs.starter || !cs.weights[m.cls]) continue;
    const list = cs.pool(m.cls);
    const i = list.findIndex((x) => x.id === m.id);
    if (i < 0) continue;
    const total = Object.values(cs.weights).reduce((a, b) => a + b, 0);
    const mw = modelWeights(list), sw = mw.reduce((a, b) => a + b, 0);
    out.push({ caseId: cs.id, pct: (cs.weights[m.cls] / total) * (mw[i] / sw) * 100 });
  }
  return out.sort((a, b) => b.pct - a.pct || CASE_BY_ID[a.caseId].price - CASE_BY_ID[b.caseId].price);
}
// What to dream of when nothing is chosen yet: a car roughly 30× what the player has (at least a legendary-class
// price, ~30M: a Lamborghini rather than a family EV), that some case drops; `seed` (the player id) picks one of the close candidates so players differ.
export const DREAM = { mult: 30, min: 30e6, max: 300e6, achMinRank: 2, achAgeMs: 12 * 3600e3 };
export function suggestDream(worth = 0, seed = 0) {
  const target = Math.min(DREAM.max, Math.max(DREAM.min, worth * DREAM.mult));
  const fit = ALL_MODELS.filter((m) => !m.secret && m.price >= target / 1.7 && m.price <= target * 1.7 && dreamChances(m.id).length);
  let list = fit.length ? fit : ALL_MODELS.filter((m) => !m.secret && rankOf(m.cls) >= 3 && dreamChances(m.id).length);
  // Cars from the rarity cases first (a country-only car is a narrower goal), then the likeliest drops.
  if (list.some((m) => !m.homeOnly)) list = list.filter((m) => !m.homeOnly);
  const best = (m) => dreamChances(m.id)[0]?.pct || 0;
  const near = list.sort((a, b) => best(b) - best(a)).slice(0, 6);
  return near.length ? near[Math.abs(Math.floor(seed)) % near.length].id : null;
}
// The text that goes with a shared drop (the photo message caption, the share/url fallback, the story caption).
export function shareCaption(modelId, serial = null) {
  const m = MODELS[modelId];
  if (!m) return '🏁 АВТОДРОП — кейси зі справжніми авто. Перший кейс безкоштовно 👇';
  // A «тиражна» from «Причал»: its name with the livery and its serial number.
  if (m.edition) return `🏁 Я виграв на «Причалі» тиражну ${m.name}${serial ? ` ${serialText(serial)}` : ''} в АВТОДРОП! Колекційна ціна ${short(m.price)}.\nВідкрий свій перший кейс безкоштовно 👇`;
  const cls = CLASSES[m.cls];
  return `🏁 Я вибив ${m.cls === 'X' ? 'секретну' : cls.name.toLowerCase().replace(/ий$/, 'у')} ${m.name} в АВТОДРОП! Колекційна ціна ${short(m.price)}.\nВідкрий свій перший кейс безкоштовно 👇`;
}
